"use client";

/**
 * 改造自 shadcn 原装 base-lyra radio-group（https://ui.shadcn.com/r/styles/base-lyra/radio-group.json，MIT）。
 * 与上游的差异：
 * 1. 动效改由 `motion` 属性选预设（ADR 0021）。`RadioGroup` 收 `motion`，经 context 交给每个 `RadioGroupItem`。
 *    缺省 `pop`：选中的圆点（`RadioPrimitive.Indicator`）渲染 `data-motion="pop"`，选中时淡入加缩放，换选时沿原路退回。
 *    `none` 与上游一致：圆点直接出现、直接消失。
 * 2. 圆点的 `-translate-x-1/2 -translate-y-1/2` 合写成 `-translate-1/2`（lint 要求）。
 * 此外只有格式化，其余类名逐字保留。
 */
import { Radio as RadioPrimitive } from "@base-ui/react/radio";
import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import { cn } from "cn";
import { createContext, use } from "react";

/**
 * 单选组支持的动效预设（ADR 0021）。缺省 `pop`。
 * - `pop`：选中的圆点淡入加缩放 96%→100%，200ms；离开的圆点 150ms 退回。
 * - `none`：圆点直接出现、直接消失。
 */
type RadioGroupMotion = "none" | "pop";

const RadioGroupMotionContext = createContext<RadioGroupMotion>("pop");

function RadioGroup({
  className,
  motion = "pop",
  ...props
}: RadioGroupPrimitive.Props & { motion?: RadioGroupMotion }) {
  return (
    <RadioGroupMotionContext value={motion}>
      <RadioGroupPrimitive
        data-slot="radio-group"
        className={cn("grid w-full gap-2", className)}
        {...props}
      />
    </RadioGroupMotionContext>
  );
}

function RadioGroupItem({ className, ...props }: RadioPrimitive.Root.Props) {
  const motion = use(RadioGroupMotionContext);
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      className={cn(
        "group/radio-group-item peer relative flex aspect-square size-4 shrink-0 rounded-full border border-input outline-none group-has-[:focus-visible]/field-label:ring-0 group-has-[:focus-visible]/field-label:not-data-checked:border-input after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 aria-invalid:aria-checked:border-primary dark:bg-input/30 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground group-has-[:focus-visible]/field-label:data-checked:border-primary dark:data-checked:bg-primary",
        className,
      )}
      {...props}
    >
      <RadioPrimitive.Indicator
        data-slot="radio-group-indicator"
        data-motion={motion === "none" ? undefined : motion}
        className="flex size-4 items-center justify-center"
      >
        <span className="absolute top-1/2 left-1/2 size-2 -translate-1/2 rounded-full bg-primary-foreground" />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  );
}

export { RadioGroup, RadioGroupItem, type RadioGroupMotion };
